import { Hono } from 'hono'
import {
  createRepairIntake,
  getRepairsList,
  getRepairById,
  transitionRepairStatus,
  updateRepairNotes,
  getCustomerWithBicycles,
  createRepairLineItem,
  updateRepairLineItem,
  deleteRepairLineItem,
  listLaborServices,
  assignWorkerToRepair,
  startWorkTimer,
  stopWorkTimer,
  completeRepairPayment,
  type RepairDetail,
  type RepairStatus,
} from '../services/repair.service.js'

const repairsRoutes = new Hono()

// ---------------------------------------------------------------------------
// GET /repairs — Paginated list of repairs with filtering and sorting
//
// Query params:
//   status       - Filter by status (intake, in_progress, on_hold, verified, ready, completed, cancelled)
//   assignedTo   - Filter by worker ID or 'unassigned' for NULL assignments
//  pickupDate    - Filter by pickup date: 'today' or 'this_week'
//   page         - Page number (1-indexed, default 1)
//   pageSize     - Items per page (default 20)
//
// Default sort: planned_date DESC (most urgent first), then created_at DESC
// ---------------------------------------------------------------------------

repairsRoutes.get('/', async (c) => {
  const status = c.req.query('status') as string | undefined
  const assignedToRaw = c.req.query('assignedTo') as string | undefined
  const pickupDateFilter = c.req.query('pickupDate') as 'today' | 'this_week' | undefined
  const page = parseInt(c.req.query('page') || '1', 10)
  const pageSize = Math.min(parseInt(c.req.query('pageSize') || '20', 10), 100) // cap at 100

  // Build filters
  const filters: Parameters<typeof getRepairsList>[0] = {}

  if (status && ['intake', 'in_progress', 'on_hold', 'verified', 'ready', 'completed', 'cancelled'].includes(status)) {
    filters.status = status as RepairStatus
  }

  if (assignedToRaw === 'unassigned') {
    filters.assignedTo = null
  } else if (assignedToRaw) {
    filters.assignedTo = assignedToRaw
  }

  if (pickupDateFilter && ['today', 'this_week'].includes(pickupDateFilter)) {
    filters.pickupDateFilter = pickupDateFilter
  }

  const result = await getRepairsList(filters, page, pageSize)
  return c.json(result)
})

// ---------------------------------------------------------------------------
// POST /repairs — Create a new repair via intake flow
//
// Accepts customer (search existing or create inline), bicycle (select from
// customer's bikes or create inline with brand/model/color), and notes.
// Repairs are created with status='intake' and assignedTo=NULL.
// ---------------------------------------------------------------------------

repairsRoutes.post('/', async (c) => {
  const input = await c.req.json()

  try {
    const repair = await createRepairIntake(input)
    return c.json(repair, 201)
  } catch (err) {
    if (err instanceof SyntaxError) {
      // Invalid JSON body
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }

    // Zod validation error or business logic error
    const message = err instanceof Error ? err.message : 'Validation failed'
    const status = (err as { code?: string; name?: string }).code === 'NOT_FOUND' || (err as { name?: string }).name === 'RepairNotFoundError' ? 404 : 400

    return c.json({ error: message, code: (err as { name?: string }).name || 'VALIDATION_ERROR' }, status)
  }
})

// ---------------------------------------------------------------------------
// GET /repairs/:id — Get single repair detail
// ---------------------------------------------------------------------------

repairsRoutes.get('/:id', async (c) => {
  const id = c.req.param('id')
  const repair = await getRepairById(id)

  if (!repair) {
    return c.json({ error: 'Repair not found', code: 'NOT_FOUND' }, 404)
  }

  return c.json(repair)
})

// ---------------------------------------------------------------------------
// PATCH /repairs/:id/status — Transition repair status (canonical endpoint)
// ---------------------------------------------------------------------------

repairsRoutes.patch('/:id/status', async (c) => {
  const id = c.req.param('id')
  const input = await c.req.json()

  try {
    const repair = await transitionRepairStatus(id, input)
    return c.json(repair as RepairDetail)
  } catch (err) {
    if (err instanceof SyntaxError) {
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }

    const message = err instanceof Error ? err.message : 'Transition failed'
    const status = (err as { name?: string }).name === 'RepairNotFoundError' ? 404 : 400

    return c.json({ error: message, code: (err as { name?: string }).name || 'VALIDATION_ERROR' }, status)
  }
})

// ---------------------------------------------------------------------------
// PATCH /repairs/:id/transition — Legacy alias for backward compatibility
// ---------------------------------------------------------------------------

repairsRoutes.patch('/:id/transition', async (c) => {
  const id = c.req.param('id')
  const input = await c.req.json()

  try {
    const repair = await transitionRepairStatus(id, input)
    return c.json(repair as RepairDetail)
  } catch (err) {
    if (err instanceof SyntaxError) {
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }

    const message = err instanceof Error ? err.message : 'Transition failed'
    const status = (err as { name?: string }).name === 'RepairNotFoundError' ? 404 : 400

    return c.json({ error: message, code: (err as { name?: string }).name || 'VALIDATION_ERROR' }, status)
  }
})

// ---------------------------------------------------------------------------
// PATCH /repairs/:id/notes — Update repair notes
// ---------------------------------------------------------------------------

repairsRoutes.patch('/:id/notes', async (c) => {
  const id = c.req.param('id')
  const input = await c.req.json()

  try {
    const repair = await updateRepairNotes(id, input)
    return c.json(repair as RepairDetail)
  } catch (err) {
    if (err instanceof SyntaxError) {
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }

    const message = err instanceof Error ? err.message : 'Update failed'
    const status = (err as { name?: string }).name === 'RepairNotFoundError' ? 404 : 400

    return c.json({ error: message, code: (err as { name?: string }).name || 'VALIDATION_ERROR' }, status)
  }
})

// ---------------------------------------------------------------------------
// GET /repairs/customers/:customerId — Get customer with bicycles for intake
// ---------------------------------------------------------------------------

repairsRoutes.get('/customers/:customerId', async (c) => {
  const customerId = c.req.param('customerId')
  const customerWithBicycles = await getCustomerWithBicycles(customerId)

  if (!customerWithBicycles) {
    return c.json({ error: 'Customer not found', code: 'NOT_FOUND' }, 404)
  }

  return c.json(customerWithBicycles)
})

// ---------------------------------------------------------------------------
// GET /labor-services — List available labor services catalog
// ---------------------------------------------------------------------------

repairsRoutes.get('/labor-services', async (c) => {
  const billingType = c.req.query('billingType') as 'hourly' | 'fixed' | undefined

  try {
    const services = await listLaborServices(billingType ? { billingType } : {})
    return c.json(services)
  } catch (err) {
    console.error('[GET /labor-services] Error:', err instanceof Error ? err.message : String(err))
    return c.json({ error: 'Failed to fetch labor services', code: 'INTERNAL_ERROR' }, 500)
  }
})

// ---------------------------------------------------------------------------
// POST /repairs/:id/items — Create a line item (part or labor)
// ---------------------------------------------------------------------------

repairsRoutes.post('/:id/items', async (c) => {
  const id = c.req.param('id')
  const input = await c.req.json()

  try {
    const item = await createRepairLineItem(id, input)
    return c.json(item, 201)
  } catch (err) {
    if (err instanceof SyntaxError) {
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }

    const message = err instanceof Error ? err.message : 'Failed to create line item'
    const status = (err as { name?: string }).name === 'RepairNotFoundError' || (err as { name?: string }).name === 'RepairCompletedError' ? 404 : 400

    return c.json({ error: message, code: (err as { name?: string }).name || 'VALIDATION_ERROR' }, status)
  }
})

// ---------------------------------------------------------------------------
// PATCH /repairs/:id/items/:itemId — Update a line item
// ---------------------------------------------------------------------------

repairsRoutes.patch('/:id/items/:itemId', async (c) => {
  const id = c.req.param('id')
  const itemId = c.req.param('itemId')
  const input = await c.req.json()

  try {
    const item = await updateRepairLineItem(id, itemId, input)
    return c.json(item)
  } catch (err) {
    if (err instanceof SyntaxError) {
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }

    const message = err instanceof Error ? err.message : 'Failed to update line item'
    const status = (err as { name?: string }).name === 'RepairNotFoundError' || (err as { name?: string }).name === 'RepairCompletedError' || (err as { name?: string }).name === 'RepairLineItemNotFoundError' ? 404 : 400

    return c.json({ error: message, code: (err as { name?: string }).name || 'VALIDATION_ERROR' }, status)
  }
})

// ---------------------------------------------------------------------------
// DELETE /repairs/:id/items/:itemId — Delete a line item
// ---------------------------------------------------------------------------

repairsRoutes.delete('/:id/items/:itemId', async (c) => {
  const id = c.req.param('id')
  const itemId = c.req.param('itemId')

  try {
    const deleted = await deleteRepairLineItem(id, itemId)
    return c.json(deleted)
  } catch (err) {
    if (err instanceof SyntaxError) {
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }

    const message = err instanceof Error ? err.message : 'Failed to delete line item'
    const status = (err as { name?: string }).name === 'RepairNotFoundError' || (err as { name?: string }).name === 'RepairCompletedError' || (err as { name?: string }).name === 'RepairLineItemNotFoundError' ? 404 : 400

    return c.json({ error: message, code: (err as { name?: string }).name || 'VALIDATION_ERROR' }, status)
  }
})

// ---------------------------------------------------------------------------
// PATCH /repairs/:id/assign — Reassign worker to repair
// ---------------------------------------------------------------------------

repairsRoutes.patch('/:id/assign', async (c) => {
  const id = c.req.param('id')
  const input = await c.req.json()

  try {
    const result = await assignWorkerToRepair(id, input)
    return c.json(result as RepairDetail)
  } catch (err) {
    if (err instanceof SyntaxError) {
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }

    const message = err instanceof Error ? err.message : 'Failed to assign worker'
    const status = (err as { name?: string }).name === 'RepairNotFoundError' ? 404 : 400

    return c.json({ error: message, code: (err as { name?: string }).name || 'VALIDATION_ERROR' }, status)
  }
})

// ---------------------------------------------------------------------------
// POST /repairs/:id/timer/start — Start a manual work timer session
//
// Creates a new work log entry with startedAt = now and endedAt = null.
// Multiple sessions can be open simultaneously on the same repair.
// ---------------------------------------------------------------------------

repairsRoutes.post('/:id/timer/start', async (c) => {
  const id = c.req.param('id')
  const input = await c.req.json()

  try {
    // Validate that userId is provided
    if (!input?.userId) {
      return c.json({ error: 'userId is required', code: 'VALIDATION_ERROR' }, 400)
    }

    const result = await startWorkTimer(id, input.userId)
    return c.json(result, 201)
  } catch (err) {
    if (err instanceof SyntaxError) {
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }

    const message = err instanceof Error ? err.message : 'Failed to start timer'
    const status = (err as { name?: string }).name === 'RepairNotFoundError' ? 404 : 400

    return c.json({ error: message, code: (err as { name?: string }).name || 'VALIDATION_ERROR' }, status)
  }
})

// ---------------------------------------------------------------------------
// POST /repairs/:id/timer/stop — Stop an active work timer session
//
// Sets endedAt on the specified work log entry. If already stopped, updates
// endedAt again (extending the recorded duration).
// ---------------------------------------------------------------------------

repairsRoutes.post('/:id/timer/stop', async (c) => {
  const input = await c.req.json()

  try {
    // Validate that workLogId is provided
    if (!input?.workLogId) {
      return c.json({ error: 'workLogId is required', code: 'VALIDATION_ERROR' }, 400)
    }

    const result = await stopWorkTimer(input.workLogId)
    return c.json(result)
  } catch (err) {
    if (err instanceof SyntaxError) {
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }

    const message = err instanceof Error ? err.message : 'Failed to stop timer'
    const status = (err as { name?: string }).name === 'WorkLogNotFoundError' || (err as { name?: string }).name === 'RepairNotFoundError' ? 404 : 400

    return c.json({ error: message, code: (err as { name?: string }).name || 'VALIDATION_ERROR' }, status)
  }
})

// ---------------------------------------------------------------------------
// POST /repairs/:id/complete — Complete repair with payment (atomic transaction)
//
// Accepts single or split payment methods. Atomically:
//   1. Validates repair is in 'ready' status
//   2. Computes total from line items and validates payment amounts match
//   3. Checks stock availability for all parts used
//   4. Creates linked Sale (sourceType='repair') with sale + line items
//   5. Creates payment records and allocations
//   6. Deducts stock via movements (reason='repair_use')
//   7. Marks repair as completed with completedAt timestamp
// All-or-nothing: any failure rolls back everything.
// ---------------------------------------------------------------------------

repairsRoutes.post('/:id/complete', async (c) => {
  const id = c.req.param('id')
  const input = await c.req.json()

  try {
    // Validate that payments array is provided and non-empty
    if (!input?.payments || !Array.isArray(input.payments) || input.payments.length === 0) {
      return c.json({ error: 'At least one payment method is required', code: 'VALIDATION_ERROR' }, 400)
    }

    // Validate each payment has method and positive amount
    for (const pay of input.payments) {
      if (!pay.method || !['cash', 'card'].includes(pay.method)) {
        return c.json({ error: `Invalid payment method: ${pay?.method}`, code: 'VALIDATION_ERROR' }, 400)
      }
      if (typeof pay.amount !== 'number' || pay.amount <= 0) {
        return c.json({ error: 'Payment amount must be a positive number', code: 'VALIDATION_ERROR' }, 400)
      }
    }

    const result = await completeRepairPayment(id, { payments: input.payments })
    return c.json(result, 200)
  } catch (err) {
    if (err instanceof SyntaxError) {
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }

    const message = err instanceof Error ? err.message : 'Payment completion failed'
    const name = (err as { name?: string }).name || ''

    // Map specific errors to appropriate HTTP status codes
    if (name === 'RepairNotFoundError') {
      return c.json({ error: message, code: 'NOT_FOUND' }, 404)
    }
    if (name === 'RepairNotReadyError') {
      return c.json({ error: message, code: 'INVALID_STATUS' }, 409)
    }
    if (name === 'PaymentMismatchError') {
      return c.json({ error: message, code: 'PAYMENT_MISMATCH' }, 422)
    }
    if (name === 'InsufficientStockForRepairError') {
      const shortfalls = (err as { shortfalls?: unknown[] }).shortfalls
      return c.json(
        { error: message, code: 'INSUFFICIENT_STOCK', shortfalls },
        422
      )
    }

    return c.json({ error: message, code: name || 'INTERNAL_ERROR' }, 500)
  }
})

export default repairsRoutes

import { Hono } from 'hono'
import { cors } from 'hono/cors'
import { logger } from 'hono/logger'
import apiRoutes from './routes/index.js'

const app = new Hono()

// Middleware
app.use('*', logger())
app.use('/api/*', cors())

// Global error handler — catches unhandled exceptions and returns structured JSON
app.onError((error, c) => {
  console.error('[UNHANDLED]', error)
  return c.json(
    { error: 'Internal server error', code: 'INTERNAL_ERROR' },
    500
  )
})

// Mount all API routes from the flat barrel
app.route('/api', apiRoutes)

// Health check
app.get('/', (c) => c.text('Pi POS Server'))
app.get('/health', (c) => c.json({ status: 'ok' }))

export default app

import type { PartDetail, CreatePartInput, UpdatePartInput, PartsCatalogResponse } from './types.js'

// ---------------------------------------------------------------------------
// API helpers — call /api/parts endpoints using explicit types
// ---------------------------------------------------------------------------

/** Fetch the active parts catalog with optional search filtering. */
export async function fetchParts(search?: string): Promise<PartsCatalogResponse> {
  const url = search ? `/api/parts?search=${encodeURIComponent(search)}` : '/api/parts'
  const res = await fetch(url)
  if (!res.ok) throw new Error('Failed to fetch parts')
  return res.json() as Promise<PartsCatalogResponse>
}

/** Fetch a single part by ID. */
export async function fetchPartById(id: string): Promise<PartDetail> {
  const res = await fetch(`/api/parts/${id}`)
  if (!res.ok) {
    const err = await res.json().catch(() => ({}))
    throw new Error(err.error ?? 'Failed to fetch part')
  }
  return res.json() as Promise<PartDetail>
}

/** Create a new part. */
export async function createPart(input: CreatePartInput): Promise<PartDetail> {
  const res = await fetch('/api/parts', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(input),
  })
  if (!res.ok) {
    const err = await res.json().catch(() => ({}))
    throw new Error(err.error ?? 'Failed to create part')
  }
  return res.json() as Promise<PartDetail>
}

/** Update an existing part with partial data. */
export async function updatePart(id: string, input: UpdatePartInput): Promise<PartDetail> {
  const res = await fetch(`/api/parts/${id}`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(input),
  })
  if (!res.ok) {
    const err = await res.json().catch(() => ({}))
    throw new Error(err.error ?? 'Failed to update part')
  }
  return res.json() as Promise<PartDetail>
}

/** Soft-disable a part. */
export async function deactivatePart(id: string): Promise<void> {
  const res = await fetch(`/api/parts/${id}/deactivate`, { method: 'PATCH' })
  if (!res.ok) {
    const err = await res.json().catch(() => ({}))
    throw new Error(err.error ?? 'Failed to deactivate part')
  }
}

import { useState, useEffect, useCallback } from 'react'
import { DataTable, type DataTableColumn } from '@/components/ui/DataTable.js'
import { CurrencyInput } from '@/components/ui/CurrencyInput.js'
import { Button } from '@/components/ui/button.js'
import { Input } from '@/components/ui/input.js'
import { Label } from '@/components/ui/label.js'
import { Textarea } from '@/components/ui/textarea.js'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
  DialogDescription,
} from '@/components/ui/dialog.js'
import { formatCentsToEuro } from '@/shared/lib/utils.js'
import { showSuccess, showError } from '@/shared/lib/notifications.js'
import { Wrench } from 'lucide-react'

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface LaborServiceCatalogItem extends Record<string, unknown> {
  id: string
  name: string
  defaultRate: number
}

interface LaborServiceDetail extends LaborServiceCatalogItem {
  description?: string
  billingType: 'hourly'
}

interface CreateLaborServiceInput {
  name: string
  description?: string
  billingType: 'hourly'
  defaultRate: number
}

interface UpdateLaborServiceInput {
  name?: string
  description?: string
  billingType?: 'hourly'
  defaultRate?: number
}

// ---------------------------------------------------------------------------
// API helpers
// ---------------------------------------------------------------------------

async function fetchLaborServices(search?: string): Promise<{ laborServices: LaborServiceCatalogItem[]; total: number }> {
  const url = search ? `/api/labor-services?search=${encodeURIComponent(search)}` : '/api/labor-services'
  const res = await fetch(url)
  if (!res.ok) throw new Error('Failed to fetch labor services')
  return res.json()
}

async function createLaborService(input: CreateLaborServiceInput): Promise<LaborServiceDetail> {
  const res = await fetch('/api/labor-services', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(input),
  })
  if (!res.ok) {
    const err = await res.json().catch(() => ({}))
    throw new Error(err.error ?? 'Failed to create labor service')
  }
  return res.json()
}

async function updateLaborService(id: string, input: UpdateLaborServiceInput): Promise<LaborServiceDetail> {
  const res = await fetch(`/api/labor-services/${id}`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(input),
  })
  if (!res.ok) {
    const err = await res.json().catch(() => ({}))
    throw new Error(err.error ?? 'Failed to update labor service')
  }
  return res.json()
}

async function deactivateLaborService(id: string): Promise<void> {
  const res = await fetch(`/api/labor-services/${id}/deactivate`, { method: 'PATCH' })
  if (!res.ok) {
    const err = await res.json().catch(() => ({}))
    throw new Error(err.error ?? 'Failed to deactivate labor service')
  }
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

export function LaborServicesPage() {
  const [laborServices, setLaborServices] = useState<LaborServiceCatalogItem[]>([])
  const [totalItems, setTotalItems] = useState(0)
  const [searchTerm, setSearchTerm] = useState('')
  const [currentPage, setCurrentPage] = useState(1)
  const pageSize = 20

  // Modal state
  const [modalOpen, setModalOpen] = useState(false)
  const [editingService, setEditingService] = useState<LaborServiceDetail | null>(null)
  const [submitting, setSubmitting] = useState(false)
  const [deactivatingId, setDeactivatingId] = useState<string | null>(null)

  // Form state
  const [formName, setFormName] = useState('')
  const [formDescription, setFormDescription] = useState('')
  const [formDefaultRate, setFormDefaultRate] = useState(0)

  // Fetch labor services on search/page change
  useEffect(() => {
    let cancelled = false
    fetchLaborServices(searchTerm || undefined).then(({ laborServices: ls, total }) => {
      if (!cancelled) {
        setLaborServices(ls)
        setTotalItems(total)
      }
    }).catch((err) => showError(err.message))

    return () => { cancelled = true }
  }, [searchTerm, currentPage])

  // Reset page when search changes
  const handleSearchChange = useCallback((term: string) => {
    setSearchTerm(term)
    setCurrentPage(1)
  }, [])

  // Open create modal
  const openCreateModal = () => {
    setEditingService(null)
    resetForm()
    setModalOpen(true)
  }

  // Open edit modal
  const openEditModal = (service: LaborServiceCatalogItem) => {
    fetch(`/api/labor-services/${service.id}`)
      .then(res => res.json())
      .then((detail: LaborServiceDetail) => {
        setEditingService(detail)
        setFormName(detail.name)
        setFormDescription(detail.description ?? '')
        setFormDefaultRate(detail.defaultRate)
        setModalOpen(true)
      })
      .catch((err) => showError(err.message))
  }

  // Close modal and reset form
  const closeModal = () => {
    setModalOpen(false)
    setEditingService(null)
    resetForm()
  }

  const resetForm = () => {
    setFormName('')
    setFormDescription('')
    setFormDefaultRate(0)
  }

  // Submit form (create or update)
  const handleSubmit = async () => {
    if (!formName.trim()) {
      showError('Name is required')
      return
    }
    if (formDefaultRate <= 0) {
      showError('Hourly rate must be greater than 0')
      return
    }

    setSubmitting(true)
    try {
      if (editingService) {
        // Update existing service
        await updateLaborService(editingService.id, {
          name: formName.trim(),
          description: formDescription.trim() || undefined,
          defaultRate: formDefaultRate,
        })
        showSuccess('Labor service updated')
      } else {
        // Create new service (billingType is always 'hourly', hidden from UI)
        await createLaborService({
          name: formName.trim(),
          description: formDescription.trim() || undefined,
          billingType: 'hourly' as const,
          defaultRate: formDefaultRate,
        })
        showSuccess('Labor service created')
      }
      closeModal()
    } catch (err) {
      showError(err instanceof Error ? err.message : 'Failed to save labor service')
    } finally {
      setSubmitting(false)
    }
  }

  // Deactivate service with confirmation
  const handleDeactivate = async (service: LaborServiceCatalogItem) => {
    if (!confirm(`Deactivate "${service.name}"? This cannot be undone.`)) return

    setDeactivatingId(service.id)
    try {
      await deactivateLaborService(service.id)
      showSuccess('Labor service deactivated')
    } catch (err) {
      showError(err instanceof Error ? err.message : 'Failed to deactivate labor service')
    } finally {
      setDeactivatingId(null)
    }
  }

  // Column definitions for the DataTable
  const columns: DataTableColumn<LaborServiceCatalogItem>[] = [
    {
      key: 'name',
      header: 'Name',
      render: (item) => <span className="font-medium">{item.name}</span>,
    },
    {
      key: 'defaultRate',
      header: 'Hourly Rate',
      render: (item) => formatCentsToEuro(item.defaultRate),
    },
    {
      key: 'actions',
      header: '',
      render: (item) => (
        <div className="flex items-center gap-2">
          <Button variant="ghost" size="sm" onClick={() => openEditModal(item)}>Edit</Button>
          <Button
            variant="ghost"
            size="sm"
            className="text-red-500 hover:text-red-600"
