export function BicycleTemplatesPage() {
  const [templates, setTemplates] = useState<BicycleTemplateCatalogItem[]>([])
  const [totalItems, setTotalItems] = useState(0)
  const [searchTerm, setSearchTerm] = useState('')
  const [currentPage, setCurrentPage] = useState(1)
  const pageSize = 20

  // Modal state
  const [modalOpen, setModalOpen] = useState(false)
  const [editingTemplate, setEditingTemplate] = useState<BicycleTemplateDetail | null>(null)
  const [submitting, setSubmitting] = useState(false)
  const [deactivatingId, setDeactivatingId] = useState<string | null>(null)

  // Form state
  const [formBrand, setFormBrand] = useState('')
  const [formModel, setFormModel] = useState('')
  const [formDescription, setFormDescription] = useState('')
  const [formBasePriceNet, setFormBasePriceNet] = useState<number | undefined>(undefined)

  // Fetch templates on search/page change
  useEffect(() => {
    let cancelled = false
    fetchBicycleTemplates(searchTerm || undefined).then(({ templates: t, total }) => {
      if (!cancelled) {
        setTemplates(t)
        setTotalItems(total)
      }
    }).catch((err) => showError(err.message))

    return () => { cancelled = true }
  }, [searchTerm, currentPage])

  // Reset page when search changes
  const handleSearchChange = useCallback((term: string) => {
    setSearchTerm(term)
    setCurrentPage(1)
  }, [])

  // Open create modal
  const openCreateModal = () => {
    setEditingTemplate(null)
    resetForm()
    setModalOpen(true)
  }

  // Open edit modal
  const openEditModal = (template: BicycleTemplateCatalogItem) => {
    fetch(`/api/bicycle-templates/${template.id}`)
      .then(res => res.json())
      .then((detail: BicycleTemplateDetail) => {
        setEditingTemplate(detail)
        setFormBrand(detail.brand)
        setFormModel(detail.model)
        setFormDescription(detail.description ?? '')
        setFormBasePriceNet(detail.basePriceNet)
        setModalOpen(true)
      })
      .catch((err) => showError(err.message))
  }

  // Close modal and reset form
  const closeModal = () => {
    setModalOpen(false)
    setEditingTemplate(null)
    resetForm()
  }

  const resetForm = () => {
    setFormBrand('')
    setFormModel('')
    setFormDescription('')
    setFormBasePriceNet(undefined)
  }

  // Submit form (create or update)
  const handleSubmit = async () => {
    if (!formBrand.trim() || !formModel.trim()) {
      showError('Brand and model are required')
      return
    }

    setSubmitting(true)
    try {
      if (editingTemplate) {
        // Update existing template
        await updateBicycleTemplate(editingTemplate.id, {
          brand: formBrand.trim(),
          model: formModel.trim(),
          description: formDescription.trim() || undefined,
          basePriceNet: formBasePriceNet,
        })
        showSuccess('Bicycle template updated')
      } else {
        // Create new template
        await createBicycleTemplate({
          brand: formBrand.trim(),
          model: formModel.trim(),
          description: formDescription.trim() || undefined,
          basePriceNet: formBasePriceNet,
        })
        showSuccess('Bicycle template created')
      }
      closeModal()
    } catch (err) {
      showError(err instanceof Error ? err.message : 'Failed to save bicycle template')
    } finally {
      setSubmitting(false)
    }
  }

  // Deactivate template with confirmation
  const handleDeactivate = async (template: BicycleTemplateCatalogItem) => {
    if (!confirm(`Deactivate "${template.brand} ${template.model}"? This cannot be undone.`)) return

    setDeactivatingId(template.id)
    try {
      await deactivateBicycleTemplate(template.id)
      showSuccess('Bicycle template deactivated')
    } catch (err) {
      showError(err instanceof Error ? err.message : 'Failed to deactivate bicycle template')
    } finally {
      setDeactivatingId(null)
    }
  }

  // Column definitions for the DataTable
  const columns: DataTableColumn<BicycleTemplateCatalogItem>[] = [
    {
      key: 'brand',
      header: 'Brand',
      render: (item) => <span className="font-medium">{item.brand}</span>,
    },
    {
      key: 'model',
      header: 'Model',
      render: (item) => <span>{item.model}</span>,
    },
    {
      key: 'basePriceNet',
      header: 'Base Price (ex. VAT)',
      render: (item) => item.basePriceNet != null ? formatCentsToEuro(item.basePriceNet) : <span className="text-muted-foreground">—</span>,
    },
    {
      key: 'actions',
      header: '',
      render: (item) => (
        <div className="flex items-center gap-2">
          <Button variant="ghost" size="sm" onClick={() => openEditModal(item)}>Edit</Button>
          <Button
            variant="ghost"
            size="sm"
            className="text-red-500 hover:text-red-600"
            disabled={deactivatingId === item.id}
            onClick={() => handleDeactivate(item)}
          >
            {deactivatingId === item.id ? '...' : 'Deactivate'}
          </Button>
        </div>
      ),
    },
  ]

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <h1 className="text-2xl font-bold">Bicycle Templates</h1>
        <Button onClick={openCreateModal}>Add Template</Button>
      </div>

      {/* DataTable */}
      <DataTable<BicycleTemplateCatalogItem>
        data={templates}
        columns={columns}
        searchTerm={searchTerm}
        onSearchChange={handleSearchChange}
        totalItems={totalItems}
        currentPage={currentPage}
        pageSize={pageSize}
        onPageChange={(page) => {
          if (page >= 1 && page <= Math.ceil(totalItems / pageSize)) {
            setCurrentPage(page)
          }
        }}
        emptyMessage={'No bicycle templates found. Click "Add Template" to create one.'}
      />

      {/* Create/Edit Modal */}
      <Dialog open={modalOpen} onOpenChange={(open) => !open && closeModal()}>
        <DialogContent className="max-w-lg">
          <DialogHeader>
            <DialogTitle>{editingTemplate ? 'Edit Template' : 'Add New Template'}</DialogTitle>
            <DialogDescription>
              {editingTemplate
                ? `Editing ${editingTemplate.brand} ${editingTemplate.model}`
                : 'Fill in the details for the new bicycle template.'}
            </DialogDescription>
          </DialogHeader>

          <div className="grid gap-4 py-4">
            {/* Brand */}
            <div className="space-y-2">
              <Label htmlFor="brand">Brand *</Label>
              <Input
                id="brand"
                value={formBrand}
                onChange={(e) => setFormBrand(e.target.value)}
                placeholder="e.g. Gazelle, Batavus, Koga"
              />
            </div>

            {/* Model */}
            <div className="space-y-2">
              <Label htmlFor="model">Model *</Label>
              <Input
                id="model"
                value={formModel}
                onChange={(e) => setFormModel(e.target.value)}
                placeholder="e.g. Ultimate C8 HMB"
              />
            </div>

            {/* Description */}
            <div className="space-y-2">
              <Label htmlFor="description">Description</Label>
              <Textarea
                id="description"
                value={formDescription}
                onChange={(e) => setFormDescription(e.target.value)}
                placeholder="Optional description"
                rows={2}
              />
            </div>

            {/* Base Price (optional) */}
            <div className="space-y-2">
              <Label htmlFor="basePriceNet">Base Price (ex. VAT)</Label>
              <CurrencyInput
                id="basePriceNet"
                value={formBasePriceNet ?? 0}
                onChange={(val) => setFormBasePriceNet(val > 0 ? val : undefined)}
              />
            </div>
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={closeModal}>Cancel</Button>
            <Button onClick={handleSubmit} disabled={submitting}>
              {submitting ? 'Saving...' : editingTemplate ? 'Save Changes' : 'Create Template'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  )
}

import * as React from 'react'
import { formatCentsToEuro } from '@/shared/lib/utils.js'

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface CurrencyInputProps extends Omit<React.InputHTMLAttributes<HTMLInputElement>, 'onChange' | 'value'> {
  /** Current value in cents (integer) */
  value: number
  /** Change callback — receives new value in cents */
  onChange: (cents: number) => void
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

/**
 * CurrencyInput — accepts decimal euros, converts to/from cents.
 *
 * Displays values as €X.XX but stores them internally as integer cents.
 * This prevents floating-point precision issues while providing a familiar
 * euro-formatted display for users.
 */
export function CurrencyInput({ value, onChange, className, ...props }: CurrencyInputProps) {
  const [displayValue, setDisplayValue] = React.useState(formatCentsToEuro(value))

  // Update display when cents change externally
  React.useEffect(() => {
    setDisplayValue(formatCentsToEuro(value))
  }, [value])

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const raw = e.target.value

    // Allow empty input during typing
    if (raw === '' || raw === '-') {
      onChange(0)
      return
    }

    // Parse decimal euros → cents
    const euroValue = parseFloat(raw.replace(',', '.'))
    if (isNaN(euroValue) || euroValue < 0) {
      return
    }

    const cents = Math.round(euroValue * 100)
    onChange(cents)
  }

  const handleBlur = () => {
    // Format to 2 decimal places on blur
    setDisplayValue(formatCentsToEuro(value))
  }

  return (
    <div className="relative">
      <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground pointer-events-none">€</span>
      <input
        type="text"
        inputMode="decimal"
        value={displayValue}
        onChange={handleChange}
        onBlur={handleBlur}
        className={`h-10 w-full rounded-md border border-input bg-background pl-7 pr-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50 ${className ?? ''}`}
        {...props}
      />
    </div>
  )
}

import { type ClassValue, clsx } from 'clsx'
import { twMerge } from 'tailwind-merge'

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

/** Generate a unique ID for optimistic UI updates.
 * Works in both browser and Node.js without crypto.randomUUID(). */
export function generateId(): string {
  return Math.random().toString(36).substring(2) + Date.now().toString(36)
}

/** Format cents (integer) to Euro string with 2 decimal places. */
export function formatCentsToEuro(cents: number): string {
  return `€${(cents / 100).toFixed(2)}`
}

import { sql } from 'drizzle-orm'
import { sqliteTable, text, integer, unique, index, check } from 'drizzle-orm/sqlite-core'

// ============================================================================
// COMPOSABLE COLUMN PRIMITIVES
// Change pricing logic = one edit. All line-item tables spread these.
// ============================================================================

/** Shared pricing contract for every line item in the system */
export const lineItemColumns = {
  lineType: text('line_type', { enum: ['part', 'labor', 'bicycle'] }).notNull(),
  partId: text('part_id').references(() => parts.id),
  laborServiceId: text('labor_service_id').references(() => laborServices.id),
  description: text('description').notNull(),
  quantity: integer('quantity', { mode: 'number' }).notNull().default(1),
  unitPriceNet: integer('unit_price_net', { mode: 'number' }).notNull(), // ex-tax cents per unit
  vatRateId: text('vat_rate_id').references(() => vatRates.id).notNull(), // FK to vatRates lookup
  discountPercent: integer('discount_percent'), // basis points, nullable = no discount
  lineTotalNet: integer('line_total_net', { mode: 'number' }).notNull(), // discounted net total
  lineTotalVat: integer('line_total_vat', { mode: 'number' }).notNull(), // VAT amount
  lineTotalGross: integer('line_total_gross', { mode: 'number' }).notNull(), // incl-tax total
}

/** Bicycle-specific details for bicycle line items */
export const bicycleLineColumns = {
  bicycleId: text('bicycle_id').references(() => bicycles.id), // link to physical instance
  bicycleBrand: text('bicycle_brand'),
  bicycleModel: text('bicycle_model'),
  bicycleYear: integer('bicycle_year', { mode: 'number' }),
  bicycleColor: text('bicycle_color'),
  bicycleFrameSize: text('bicycle_frame_size'),
}

/** CHECK constraints for line item tables — applied per-table via extras callback */
export const lineItemChecks = () => ({
  totalsNonNegative: check(
    'line_totals_non_negative',
    sql`${sql.identifier('line_total_net')} >= 0 AND ${sql.identifier('line_total_vat')} >= 0 AND ${sql.identifier('line_total_gross')} >= 0`
  ),
})

// ============================================================================
// CORE ENTITIES — Customers, Staff, Tax
// ============================================================================

/** Who we serve — private individuals or companies. Anonymous walk-ins have no row. */
export const customers = sqliteTable('customers', {
  id: text('id').primaryKey(),
  type: text('type', { enum: ['private', 'company'] }).notNull().default('private'),
  firstName: text('first_name'), // required for private
  lastName: text('last_name'), // required for private
  companyName: text('company_name'), // required for company
  vatId: text('vat_id'), // for companies
  phone: text('phone'),
  email: text('email'),
  street: text('street'),
  number: text('number'),
  bus: text('bus'),
  postalCode: text('postal_code'),
  city: text('city'),
  country: text('country').notNull().default('BE'), // Belgium default
  notificationPreference: text('notification_preference', { enum: ['sms', 'email'] }),
})

export type Customer = typeof customers.$inferSelect
export type NewCustomer = typeof customers.$inferInsert

/** Shop staff — mechanics and managers with hourly rates */
export const users = sqliteTable('users', {
  id: text('id').primaryKey(),
  name: text('name').notNull(),
  role: text('role', { enum: ['mechanic', 'manager'] }).notNull().default('mechanic'),
  hourlyRate: integer('hourly_rate', { mode: 'number' }).notNull(),
  isActive: integer('is_active', { mode: 'boolean' }).notNull().default(true),
  createdAt: integer('created_at', { mode: 'timestamp' }).$defaultFn(() => new Date()).notNull(),
})

export type User = typeof users.$inferSelect
export type NewUser = typeof users.$inferInsert

/** VAT rate lookup — e.g. standard 21%, reduced 6% */
export const vatRates = sqliteTable('vat_rates', {
  id: text('id').primaryKey(),
  rate: integer('rate').notNull().unique(), // basis points: 2100 = 21%, 600 = 6%
  description: text('description').notNull(),
})

export type VatRate = typeof vatRates.$inferSelect
export type NewVatRate = typeof vatRates.$inferInsert

// ============================================================================
// CATALOG — Parts, Labor Services, Bicycle Templates
// ============================================================================

/** Physical products with stock tracking */
export const parts = sqliteTable('parts', {
  id: text('id').primaryKey(),
  barcode: text('barcode').notNull().unique(),
  name: text('name').notNull(),
  description: text('description'),
  priceNet: integer('price_net', { mode: 'number' }).notNull(), // ex-tax cents
  costPrice: integer('cost_price', { mode: 'number' }), // in cents
  quantityOnHand: integer('quantity_on_hand', { mode: 'number' }).notNull().default(0),
  isActive: integer('is_active', { mode: 'boolean' }).notNull().default(true),
}, (table) => ({
  activeIdx: index('parts_active_idx').on(table.isActive),
}))

export type Part = typeof parts.$inferSelect
export type NewPart = typeof parts.$inferInsert

/** Labor services — hourly or fixed-rate work types */
export const laborServices = sqliteTable('labor_services', {
  id: text('id').primaryKey(),
  name: text('name').notNull(),
  description: text('description'),
  billingType: text('billing_type', { enum: ['hourly', 'fixed'] }).notNull(),
  defaultRate: integer('default_rate', { mode: 'number' }).notNull(), // cents/hour or fixed amount
  isActive: integer('is_active', { mode: 'boolean' }).notNull().default(true),
})

export type LaborService = typeof laborServices.$inferSelect
export type NewLaborService = typeof laborServices.$inferInsert

/** Bicycle catalog templates — become real bicycles when sold or taken in */
export const bicycleTemplates = sqliteTable('bicycle_templates', {
  id: text('id').primaryKey(),
  brand: text('brand').notNull(),
  model: text('model').notNull(),
  description: text('description'),
  basePriceNet: integer('base_price_net', { mode: 'number' }), // optional catalog price in cents
  isActive: integer('is_active', { mode: 'boolean' }).notNull().default(true),
})

export type BicycleTemplate = typeof bicycleTemplates.$inferSelect
export type NewBicycleTemplate = typeof bicycleTemplates.$inferInsert

// ============================================================================
// BICYCLES — Physical Instances
// ============================================================================

/** Real bicycles — customer-owned or shop inventory */
export const bicycles = sqliteTable('bicycles', {
  id: text('id').primaryKey(),
  source: text('source', { enum: ['inventory', 'customer_owned'] }).notNull().default('customer_owned'),
  templateId: text('template_id').references(() => bicycleTemplates.id), // nullable for customer-owned
  customerId: text('customer_id').references(() => customers.id), // required when source = 'customer_owned'
  brand: text('brand').notNull(), // snapshotted from template or entered manually
  model: text('model').notNull(),
  year: integer('year', { mode: 'number' }),
  color: text('color'),
  frameSize: text('frame_size'),
  status: text('status', { enum: ['inventory', 'in_shop', 'ready_for_pickup', 'returned', 'sold'] })
    .notNull().default('inventory'),
  createdAt: integer('created_at', { mode: 'timestamp' }).$defaultFn(() => new Date()).notNull(),
}, (table) => ({
  customerIdIdx: index('bicycles_customer_id_idx').on(table.customerId),
  sourceCustomerCheck: check(
    'bicycles_source_customer_check',
    sql`(${sql.identifier('source')} = 'customer_owned' AND ${sql.identifier('customer_id')} IS NOT NULL) OR (${sql.identifier('source')} = 'inventory' AND ${sql.identifier('customer_id')} IS NULL)`
  ),
}))

export type Bicycle = typeof bicycles.$inferSelect
export type NewBicycle = typeof bicycles.$inferInsert

// ============================================================================
// WORKING DOCUMENTS — Quotes, Repairs, Customer Orders, Backorders
// ============================================================================

/** Estimates/proposals — immutable once sent. Copied to Order or Repair on approval. */
export const quotes = sqliteTable('quotes', {
  id: text('id').primaryKey(),
  quoteNumber: text('quote_number').notNull().unique(), // QT-0001
  customerId: text('customer_id').references(() => customers.id), // nullable during draft
  status: text('status', { enum: ['draft', 'sent', 'converted', 'rejected'] })
    .notNull().default('draft'),
  notes: text('notes'),
  createdAt: integer('created_at', { mode: 'timestamp' }).$defaultFn(() => new Date()).notNull(),
  updatedAt: integer('updated_at', { mode: 'timestamp' }).$defaultFn(() => new Date()).notNull(),
}, (table) => ({
  statusIdx: index('quotes_status_idx').on(table.status),
  customerRequiredCheck: check(
    'quotes_customer_required_check',
    sql`${sql.identifier('status')} = 'draft' OR ${sql.identifier('customer_id')} IS NOT NULL`
  ),
}))

export type Quote = typeof quotes.$inferSelect
export type NewQuote = typeof quotes.$inferInsert

/** Quote line items — snapshotted pricing per line */
export const quoteLineItems = sqliteTable('quote_line_items', {
